/*
 * Configuration.cs - desktop geometry for every tab.
 *
 * CFG_DESK_LAYOUT (generated from InitializeComponent of
 * recovered_source/ECCOUNTBOOKERP/Architecture.WinApp.Configurations/Configuration.cs) carries each
 * control's Location, Size, Text, Font, ForeColor/BackColor, Dock, Visible and Controls.Add parent.
 * This script rebuilds each tab at those coordinates and MOVES the existing web inputs (same id as
 * the desktop control Name, or the same AccessibleName) into place, so every load/save handler in
 * countx_configuration.js keeps working unchanged. The desktop labels are drawn from the layout.
 *
 * Configurations_Load() runtime visibility is applied too:
 *   ERP feature 4  -> chkInCasefSubsidiaryShowBothVendorAndCustomerOnSalesPurchase, label273
 *   ERP feature 8  -> GBRegularWagesPartyProcessing, GBOtherWagesPartyProcessing, GBCommonWagesPartyProcessing
 *   ERP feature 11 -> GbBranchWiseConfigPurchase, GbBranchWiseConfigSale
 */
(function ($) {
    "use strict";
    var L = window.CFG_DESK_LAYOUT;
    if (!L) return;

    var TAB_FONT = ['Verdana', 8.25, 'Regular'];   // ConfigurationsTab.Font
    var FEATURE_VISIBILITY = {
        4: ['chkInCasefSubsidiaryShowBothVendorAndCustomerOnSalesPurchase', 'label273'],
        8: ['GBRegularWagesPartyProcessing', 'GBOtherWagesPartyProcessing', 'GBCommonWagesPartyProcessing'],
        11: ['GbBranchWiseConfigPurchase', 'GbBranchWiseConfigSale']
    };

    function fontCss(f) {
        var st = (f[2] || '').toLowerCase();
        return {
            'font-family': '"' + f[0] + '", "Segoe UI", Tahoma, sans-serif',
            'font-size': f[1] + 'pt',
            'font-weight': st.indexOf('bold') >= 0 || /semibold/i.test(f[0]) ? '600' : '400',
            'font-style': st.indexOf('italic') >= 0 ? 'italic' : 'normal'
        };
    }

    function place($box, n) {
        var css = { left: n.x + 'px', top: n.y + 'px', width: n.w + 'px', height: n.h + 'px' };
        if (n.d === 'Fill') { css.right = '0'; css.bottom = '0'; css.width = 'auto'; css.height = 'auto'; }
        else if (n.d === 'Top') { css.left = '0'; css.right = '0'; css.width = 'auto'; }
        else if (n.d === 'Left') { css.top = '0'; css.bottom = '0'; css.height = 'auto'; }
        $box.css(css);
        if (n.v === 0) $box.addClass('desk-hidden');
        if (n.bc) $box.css('background-color', n.bc);
        if (n.fc) $box.css('color', n.fc);
        return $box;
    }

    function findWebControl(n) {
        var $el = $('#' + n.n);
        if (!$el.length && n.an) $el = $('[data-config-description="' + n.an.replace(/"/g, '\\"') + '"]').first();
        return $el;
    }

    function textAlign($box, ta) {
        if (!ta) return;
        if (/Right/.test(ta)) $box.css('justify-content', 'flex-end').css('text-align', 'right');
        else if (/Center/.test(ta)) $box.css('justify-content', 'center').css('text-align', 'center');
        if (/^Middle/.test(ta)) $box.css('align-items', 'center');
        else if (/^Bottom/.test(ta)) $box.css('align-items', 'flex-end');
    }

    function render(n, $parent, font) {
        var f = n.f || font;
        var $box, $el;
        switch (n.t) {
            case 'Label':
                $box = place($('<div class="desk-n desk-label">'), n).attr('id', 'desk_' + n.n).css(fontCss(f)).text(n.tx || '');
                if (n.as) $box.css({ width: 'auto', height: 'auto', 'white-space': 'pre' });
                else { $box.addClass('desk-label-fixed'); textAlign($box, n.ta); }
                break;
            case 'GroupBox':
                $box = place($('<div class="desk-n desk-group">'), n).attr('id', 'desk_' + n.n).css(fontCss(f));
                $box.append('<div class="desk-gframe"></div>');
                if (n.tx) $box.append($('<span class="desk-glegend">').text(n.tx));
                (n.c || []).forEach(function (ch) { render(ch, $box, f); });
                break;
            case 'Panel':
                $box = place($('<div class="desk-n desk-panel">'), n).attr('id', 'desk_' + n.n).css(fontCss(f));
                if (n.n === 'PanelWages02' && $('#PanelWages02').length) {
                    // Document Wise Wages Configuration grid (web PanelWages02 already carries the
                    // desktop caption strip + grid + Status Update); placed where the desktop docks it.
                    $box.append($('#PanelWages02').addClass('desk-fill'));
                } else {
                    (n.c || []).forEach(function (ch) { render(ch, $box, f); });
                }
                break;
            case 'TabControl':
                $box = place($('<div class="desk-n desk-tabctl">'), n).attr('id', 'desk_' + n.n).css(fontCss(f));
                var $strip = $('<div class="desk-tabstrip">').appendTo($box);
                (n.c || []).forEach(function (pg, i) {
                    var $pg = render(pg, $box, f);
                    $pg.toggle(i === 0);
                    $('<button type="button" class="desk-tabbtn">').text(pg.tx || pg.n).toggleClass('active', i === 0)
                        .appendTo($strip).on('click', function () {
                            $strip.children().removeClass('active'); $(this).addClass('active');
                            $box.children('.desk-page').hide(); $pg.show();
                        });
                });
                break;
            case 'TabPage':
                $box = place($('<div class="desk-n desk-page">'), n).attr('id', 'desk_' + n.n).css(fontCss(f));
                (n.c || []).forEach(function (ch) { render(ch, $box, f); });
                break;
            case 'CheckBox':
            case 'RadioButton':
                $el = findWebControl(n);
                $box = place($('<label class="desk-n desk-check">'), n).css(fontCss(f));
                if ($el.length) $box.append($el.addClass('desk-moved'));
                if (n.tx) $box.append($('<span>').text(n.tx));
                if (!$el.length) $box.addClass('desk-missing').attr('title', 'No web control for ' + n.n);
                break;
            case 'TextBox':
            case 'DateTimePicker':
                $el = findWebControl(n);
                $box = place($('<div class="desk-n desk-input">'), n).css(fontCss(f));
                if ($el.length) $box.append($el.addClass('desk-moved'));
                break;
            case 'UltraCombo':
            case 'ComboBox':
                $el = findWebControl(n);
                $box = place($('<div class="desk-n desk-input desk-combo">'), n).css(fontCss(f));
                if ($el.length) {
                    var $s2 = $el.next('.select2-container');
                    $box.append($el.addClass('desk-moved'));
                    if ($s2.length) $box.append($s2.css('width', '100%'));
                }
                break;
            case 'Button':
                // Browse... buttons open a local FolderBrowserDialog on the desktop - no web counterpart.
                $box = place($('<div class="desk-n">'), n);
                $box.append($('<button type="button" class="desk-btn" disabled>').text(n.tx || '').css(fontCss(f))
                    .attr('title', 'Local folder browser on the desktop only'));
                break;
            default:
                return $();
        }
        $parent.append($box);
        return $box;
    }

    function extent(n) {
        var w = 0, h = 0;
        (n.c || []).forEach(function (ch) {
            if (ch.v === 0) return;
            w = Math.max(w, ch.x + ch.w); h = Math.max(h, ch.y + ch.h);
        });
        return { w: Math.max(w, n.w || 0), h: Math.max(h, n.h || 0) };
    }

    function build() {
        Object.keys(L).forEach(function (tab) {
            var n = L[tab], $pane = $('#' + tab);
            if (!$pane.length) return;
            var e = extent(n);
            var $scroll = $('<div class="desk-scroll">');
            var $canvas = $('<div class="desk-canvas">').css({ width: e.w + 'px', height: e.h + 'px' })
                .css(fontCss(n.f || TAB_FONT)).appendTo($scroll);
            (n.c || []).forEach(function (ch) { render(ch, $canvas, n.f || TAB_FONT); });
            $pane.children().addClass('desk-orig');
            $pane.append($scroll).addClass('desk-pane');
        });
        $.getJSON('/api/configurations/erp-features').done(function (ids) {
            var on = {};
            (ids || []).forEach(function (i) { on[i] = true; });
            Object.keys(FEATURE_VISIBILITY).forEach(function (fid) {
                FEATURE_VISIBILITY[fid].forEach(function (name) {
                    var $t = $('#desk_' + name);
                    if (!$t.length) $t = $('#' + name).closest('.desk-n');
                    $t.toggleClass('desk-hidden', !on[fid]);
                });
            });
        });
    }

    $(function () { setTimeout(build, 0); });
})(jQuery);
